#include <stdio.h>
#include <stdlib.h>

static int compare_ints(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

int main(void) {
    int N, K, C;
    if (scanf("%d %d %d", &N, &K, &C) != 3) return 0;

    int *A = malloc((size_t)N * sizeof(int));
    long long total = 0;

    for (int i = 0; i < N; ++i) {
        scanf("%d", &A[i]);
        total += A[i];
    }

    long long min_covered;

    if (C == 1) {
        qsort(A, (size_t)N, sizeof(int), compare_ints);
        min_covered = 0;
        for (int i = 0; i < K; ++i) min_covered += A[i];
    } else {
        long long *prefix = malloc((size_t)(N + 1) * sizeof(long long));
        for (int i = 0; i < N; ++i)
            prefix[i + 1] = prefix[i] + A[i];

        const long long INF = 1LL << 60;
        long long *prev = malloc((size_t)(N + 1) * sizeof(long long));
        long long *curr = malloc((size_t)(N + 1) * sizeof(long long));

        for (int i = 0; i <= N; ++i) prev[i] = 0;

        for (int k = 1; k <= K; ++k) {
            for (int i = 0; i <= N; ++i) curr[i] = INF;

            for (int i = k * C; i <= N; ++i) {
                curr[i] = curr[i - 1];

                long long segment = prefix[i] - prefix[i - C];
                long long candidate = prev[i - C] + segment;
                if (candidate < curr[i]) curr[i] = candidate;
            }

            long long *tmp = prev;
            prev = curr;
            curr = tmp;
        }

        min_covered = prev[N];
        free(prefix);
        free(prev);
        free(curr);
    }

    printf("%lld\n", total - min_covered);
    free(A);
    return 0;
}
